npm run db:reset; echo "exit=$?"; node -e '
const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync("data/tasks.db");
console.log(JSON.stringify(db.prepare("select name from schema_migrations order by name").all()));
console.log(db.prepare("select sql from sqlite_master where name = \"tasks\"").get().sql);
db.prepare("insert into tasks (title, estimate_hours) values (?, ?)").run("check-boundary", 60);
try { db.prepare("insert into tasks (title, estimate_hours) values (?, ?)").run("over", 61); console.log("61 ACCEPTED — BAD"); }
catch (e) { console.log("61 rejected:", e.message); }
console.log(JSON.stringify(db.prepare("select id, title, estimate_hours from tasks").all()));
'

TMPD=$(mktemp -d) && node --experimental-strip-types --input-type=module -e "
import { openDb } from './lib/db.ts';
import { readFileSync } from 'node:fs';
import { DatabaseSync } from 'node:sqlite';
const file = process.argv[1] + '/legacy.db';
// Simulate a pre-003 database: apply only 001 and 002, then add rows.
const db = new DatabaseSync(file);
db.exec('create table if not exists schema_migrations (name text primary key, applied_at text not null)');
for (const m of ['db/migrations/001_create_tasks.sql', 'db/migrations/002_add_task_estimate.sql']) {
  db.exec(readFileSync(m, 'utf8'));
  db.prepare('insert into schema_migrations (name, applied_at) values (?, ?)').run(m.split('/').pop(), new Date().toISOString());
}
db.prepare('insert into tasks (title, assignee, estimate_hours) values (?, ?, ?)').run('legacy one', 'ana', 5);
db.prepare('insert into tasks (title, estimate_hours) values (?, ?)').run('legacy two', 40);
db.close();
// Now open through openDb: 003 must apply over existing data.
const db2 = openDb(file);
console.log(JSON.stringify(db2.prepare('select id, title, estimate_hours, status, created_at is not null as has_ts from tasks order by id').all()));
const fresh = db2.prepare(\"insert into tasks (title, estimate_hours) values ('new row', 60)\");
fresh.run();
console.log('next autoincrement id:', JSON.stringify(db2.prepare('select id, title from tasks order by id desc limit 1').get()));
" "$TMPD" 2>&1 | grep -v -e ExperimentalWarning -e trace-warnings; rm -rf "$TMPD"
